2517	        let MultiBufferSnapshot {
2518	            excerpts,
2519	            diffs: buffer_diff,
2520	            buffers: buffer_snapshots,
2521	            path_keys: _,
2522	            diff_transforms: _,
2523	            non_text_state_update_count,
2524	            edit_count,
2525	            is_dirty,
2526	            has_deleted_file,
2527	            has_conflict,
2528	            has_inverted_diff: _,
2529	            singleton: _,
2530	            trailing_excerpt_update_count: _,
2531	            all_diff_hunks_expanded: _,
2532	            show_deleted_hunks: _,
2533	            use_extended_diff_range: _,
2534	            show_headers: _,
