2536	        *is_dirty = false;
2537	        *has_deleted_file = false;
2538	        *has_conflict = false;
2539	
2540	        if !diffs.is_empty() {
2541	            let mut diffs_to_add = Vec::new();
2542	            for (id, diff) in diffs {
2543	                if find_diff_state(buffer_diff, *id).is_none_or(|existing_diff| {
2544	                    if existing_diff.main_buffer.is_none() {
2545	                        return false;
