pub fn row_infos(&self, start_row: MultiBufferRow) -> MultiBufferRows<'_> {
    let mut cursor = self.cursor::<Point, Point>();
    cursor.seek(&Point::new(start_row.0, 0));
    let mut result = MultiBufferRows {
        point: Point::new(0, 0),
        is_empty: self.excerpts.is_empty(),
